//! The input database must be generated by the exact predecessor, not downgraded.
use atlas_store::{
    archive::inspect_archive,
    genealogy::{Parentage, ParentageKind},
    network::{NetworkInput, NetworkKind},
    semantic::{FactFamily, FactRef, SemanticFactData},
    *,
};
use serde::Deserialize;
use std::path::PathBuf;
use uuid::Uuid;

#[derive(Deserialize)]
struct Baseline {
    schema: i64,
    world: WorldId,
    branch: BranchId,
    first: i64,
    revision: i64,
    network: Uuid,
    parentage: Uuid,
}

#[test]
#[ignore = "CI generates the database with the pinned schema-36 predecessor"]
fn released_schema_36_preserves_identity_history_and_verified_recovery()
-> Result<(), Box<dyn std::error::Error>> {
    let path = PathBuf::from(std::env::var_os("ATLAS_SCHEMA36_FIXTURE").ok_or("fixture required")?);
    let expected: Baseline = serde_json::from_slice(&std::fs::read(path.with_extension("json"))?)?;
    let before = inspect_archive(&path, Scope::Author)?;
    assert_eq!(expected.schema, 36);
    assert_eq!(before.schema, 36);
    assert_eq!(before.worlds.len(), 1);
    assert_eq!(before.worlds[0].id, expected.world);
    assert_eq!(before.worlds[0].revision, AuthorRevision(expected.revision));

    let store = Store::open_with_migration_backup(&path)?;
    let object = |number| ObjectRef {
        world: expected.world,
        id: ObjectId(Uuid::from_u128(number)),
    };
    let view = ViewContext {
        world: expected.world,
        branch: expected.branch,
        day: WorldDay(13),
        revision: AuthorRevision(expected.revision),
        scope: Scope::Author,
    };
    let historical = ViewContext {
        revision: AuthorRevision(expected.first),
        ..view
    };
    let original = store
        .get_object(object(2), historical)?
        .ok_or("original identity")?;
    let current = store
        .get_object(object(2), view)?
        .ok_or("corrected identity")?;
    assert_eq!(original.record.label, "Alice Vale");
    assert_eq!(current.record.label, "Alice Thorne");
    assert_eq!(original.object, current.object);
    assert_eq!(current.record.source, Some(object(1)));
    let membership = FactRef {
        world: expected.world,
        family: FactFamily::Network,
        id: expected.network,
    };
    let parentage = FactRef {
        world: expected.world,
        family: FactFamily::Parentage,
        id: expected.parentage,
    };
    let member = store
        .resolve_semantic_fact(membership, view)?
        .ok_or("membership")?;
    assert_eq!(member.reference, membership);
    assert_eq!(member.source_branch, expected.branch);
    assert_eq!(member.recorded_at, AuthorRevision(expected.first + 1));
    assert_eq!(
        member.data,
        SemanticFactData::Network(NetworkInput {
            subject: object(3),
            target: object(4),
            source: object(1),
            kind: NetworkKind::Membership,
            role: "member".into(),
            starts_at: 10,
            ends_before: None,
        })
    );
    let parent = store
        .resolve_semantic_fact(parentage, view)?
        .ok_or("parentage")?;
    assert_eq!(parent.reference, parentage);
    assert_eq!(parent.source_branch, expected.branch);
    assert_eq!(parent.recorded_at, AuthorRevision(expected.first + 2));
    assert_eq!(
        parent.data,
        SemanticFactData::Parentage(Parentage {
            parent: object(2),
            child: object(3),
            kind: ParentageKind::Biological,
            valid: ValidInterval {
                start: Some(WorldDay(0)),
                end_exclusive: None,
            },
            accepted: true,
        })
    );
    assert!(
        store
            .resolve_semantic_fact(membership, historical)?
            .is_none()
    );
    assert!(
        store
            .resolve_semantic_fact(parentage, historical)?
            .is_none()
    );
    assert!(
        store
            .classifications(view, Some(object(2)), None)?
            .is_empty()
    );
    store.verify_foreign_keys(Scope::Author)?;
    drop(store);
    let prefix = format!(
        "{}.pre-schema-36-",
        path.file_name()
            .ok_or("fixture filename")?
            .to_string_lossy()
    );
    let copies = std::fs::read_dir(path.parent().ok_or("fixture parent")?)?
        .collect::<Result<Vec<_>, _>>()?
        .into_iter()
        .filter(|item| item.file_name().to_string_lossy().starts_with(&prefix))
        .collect::<Vec<_>>();
    assert_eq!(copies.len(), 1);
    assert_eq!(inspect_archive(copies[0].path(), Scope::Author)?, before);
    let restored = path.with_file_name("verified-restoration.sqlite");
    atlas_store::archive::restore_archive(&copies[0].path(), &restored, Scope::Author)?;
    let store = Store::open(&restored)?;
    assert_eq!(store.resolve_semantic_fact(membership, view)?, Some(member));
    assert_eq!(store.resolve_semantic_fact(parentage, view)?, Some(parent));
    assert_eq!(store.get_object(object(2), view)?, Some(current));
    assert_eq!(inspect_archive(&path, Scope::Author)?.schema, 44);
    println!("released_schema_36_migration_and_recovery=verified");
    Ok(())
}
